namespace Curl.Tls;

/// <summary>
/// Handshake messages copied byte for byte from RFC 8448 ("Example Handshake Traces for
/// TLS 1.3"), each with its header, and the section it comes from.
/// </summary>
internal static class Rfc8448Messages
{
    // Section 3, "Simple 1-RTT Handshake": {client} construct a ClientHello handshake message.
    public const string SimpleClientHello =
        "";

    // Section 3: {server} construct a ServerHello handshake message.
    public const string SimpleServerHello =
        "020000560303a6af06a4121860dc5e6e60249cd34c95930c8ac5cb1434dac155772ed3e2692800130100002e00330024001d0020c9828876112095fe66762bdbf7c672e156d6cc253b833df1dd69b1b04e751f0f002b00020304";

    // Section 3: {server} construct an EncryptedExtensions handshake message.
    public const string SimpleEncryptedExtensions =
        "080000240022000a00140012001d00170018001901000101010201030104001c0002400100000000";

    // Section 3: {server} construct a Certificate handshake message.
    public const string SimpleCertificate =
        "";

    // Section 3: {server} construct a CertificateVerify handshake message.
    public const string SimpleCertificateVerify =
        "0f000084080400805a747c5d88fa9bd2e55ab085a61015b7211f824cd484145ab3ff52f1fda8477b0b7abc90db78e2d33a5c141a078653fa6bef780c5ea248eeaaa785c4f394cab6d30bbe8d4859ee511f602957b15411ac027671459e46445c9ea58c181e818e95b8c3fb0bf3278409d3be152a3da5043e063dda65cdf5aea20d53dfacd42f74f3";

    // Section 3: {server} construct a Finished handshake message.
    public const string SimpleServerFinished =
        "140000209b9b141d906337fbd2cbdce71df4deda4ab42c309572cb7fffee5454b78f0718";

    // Section 3: {client} construct a Finished handshake message.
    public const string SimpleClientFinished =
        "14000020a8ec436d677634ae525ac1fcebe11a039ec17694fac6e98527b642f2edd5ce61";

    // Section 3: {server} construct a NewSessionTicket handshake message.
    public const string SimpleNewSessionTicket =
        "";

    // Section 4, "Resumed 0-RTT Handshake": {client} send handshake record, payload (the
    // ClientHello with its binder).
    public const string ResumedClientHello =
        "";

    // Section 4: {server} construct a ServerHello handshake message.
    public const string ResumedServerHello =
        "0200005c03033ccfd2dec890222763472ae8136777c9d7358777bb66e91ea5122495f559ea2d00130100003400290002000000330024001d0020121761ee42c333e1b9e77b60dd57c2053cd94512ab47f115e86eff50942cea31002b00020304";

    // Section 4: {server} construct an EncryptedExtensions handshake message (early_data accepted).
    public const string ResumedEncryptedExtensions =
        "080000280026000a00140012001d00170018001901000101010201030104001c0002400100000000002a0000";

    // Section 4: {server} construct a Finished handshake message.
    public const string ResumedServerFinished = "1400002048d3e0e1b3d907c6acff145e16090388c77b05c050b634ab1a88bbd0dd1a34b2";

    // Section 4: {client} construct an EndOfEarlyData handshake message.
    public const string ResumedEndOfEarlyData = "05000000";

    // Section 4: {client} construct a Finished handshake message.
    public const string ResumedClientFinished = "140000207230a9c952c25cd6138fc5e6628308c41c5335dd81b9f96bcea50fd32bda416d";

    // Section 5, "HelloRetryRequest": {server} construct a ServerHello handshake message
    // (the HelloRetryRequest).
    public const string HelloRetryRequest =
        "";

    // Section 5: {client} construct a ClientHello handshake message (the first, with an
    // x25519 key share).
    public const string RetryFirstClientHello =
        "";

    // Section 5: {client} construct a ClientHello handshake message (the second, with a
    // P-256 key share, the cookie and padding).
    public const string RetrySecondClientHello =
        "";

    // Section 5: {server} construct a ServerHello handshake message (the second, the real
    // ServerHello with its P-256 key share).
    public const string RetryServerHello =
        "020000770303bb341d847fd789c47c387172dc0c9bf147fccacb5043d86ca4c598d3ff571b9800130100004f003300450017004104583e054b7a66672ae020ad9d2686fcc85b5ad41a134a0f03ee72b893052bd85b4c8de6776f5b04ac07d83540eab3e3d9c547bc6528c4317d294686093a6cad7d002b00020304";

    // Section 5: {server} construct an EncryptedExtensions handshake message.
    public const string RetryEncryptedExtensions = "080000180016000a0008000600170018001d001c0002400100000000";

    // Section 5: {server} construct a CertificateVerify handshake message (the Certificate
    // is the same as section 3's).
    public const string RetryCertificateVerify =
        "0f0000840804008033ab13d4462707231b5dcae6c8190b63d1dabc74f28c395370da0b07e5b83066d0246a31acd95df475bfd799a4a70d33ad93d3a317a9b2c0d237a5685b219e774112e391a247607d1aeff1bbd0a39f382ee1a5fe88ae99ec59228e6497e45d48ce275a6d5ef40d169fb6f9d33b052ed3dcdd6b5a48baafffbcb290128415bd38";

    // Section 5: {server} construct a Finished handshake message.
    public const string RetryServerFinished = "140000208863e6bfb0420a927fa27f34336a70ae426e968e3eb884945b96856dba3976d1";

    // Section 5: {client} construct a Finished handshake message.
    public const string RetryClientFinished = "1400002023f52fdb0709a55bd7f79b991f25484087bcfd4d4380b12326a52a28b2e368e1";

    // Section 6, "Client Authentication": {server} construct a CertificateRequest handshake
    // message.
    public const string ClientAuthenticationCertificateRequest =
        "0d000027000024000d0020001e040305030603020308040805080604010501060102010402050206020202";

    // Section 6: {client} construct a ClientHello handshake message.
    public const string ClientAuthenticationClientHello =
        "";

    // Section 6: {server} construct a ServerHello handshake message.
    public const string ClientAuthenticationServerHello =
        "0200005603033b50fdf1c3d572e40e68953e7fff4e2758459c59afa0582c0ea032874255fe6e00130100002e00330024001d00206c2e50e865919a6b5a12dfaf918f92b442567b0f89bc54478c6921366658f062002b00020304";

    // Section 6: {server} construct an EncryptedExtensions handshake message.
    public const string ClientAuthenticationEncryptedExtensions =
        "080000240022000a00140012001d00170018001901000101010201030104001c0002400100000000";

    // Section 6: {server} construct a Certificate handshake message (an ECDSA P-256 certificate).
    public const string ClientAuthenticationServerCertificate =
        "";

    // Section 6: {server} construct a CertificateVerify handshake message (ecdsa_secp256r1_sha256).
    public const string ClientAuthenticationServerCertificateVerify =
        "0f00004b040300473045022100d7a4d34bd54f55fee1a89625678c3dd5e5f60dac73ec940c5c7b9304a02084a90220289f595ed488b9ac689a3d192b1a8bb38f34af7874c059c9806a1f38269353e8";

    // Section 6: {server} construct a Finished handshake message.
    public const string ClientAuthenticationServerFinished = "1400002093b70cdf4781985b96345caac701b4e750d3042df1a689d8faca812251113c11";

    // Section 6: {client} construct a Certificate handshake message (an RSA certificate whose
    // private key the RFC does not publish).
    public const string ClientAuthenticationClientCertificate =
        "";

    // Section 6: {client} construct a CertificateVerify handshake message (rsa_pss_rsae_sha256).
    public const string ClientAuthenticationClientCertificateVerify =
        "0f00008408040080186b2223b503a759c35dba0e9721b4b579138d5f0f5e6ec7feaaf27f3ad7f386c2c7bd7cb2be52fbf5ed8393f406ee79369692ec7ac695651d858219e672a8eb7b2a677b640b46ab630edc5f3f2f8272b9c0d906f81f84ddc5b8c7bcf955c78a3cf99e5016f73e04eb7dfcb28833f13e8f75ec2ff3581e2f098ad4157fd6d6ad";

    // Section 6: {client} construct a Finished handshake message.
    public const string ClientAuthenticationClientFinished = "140000209afe2ba2f63a09d229d8a429e5b37ffd9fcc73bdb5911b82425972aa2892440f";

    /// <summary>Returns the body of the hexadecimal handshake message <paramref name="message" />, checking its header names <paramref name="type" />.</summary>
    public static byte[] Body(string message, HandshakeType type)
    {
        HandshakeMessageReadResult read = HandshakeMessageReader.Read(Convert.FromHexString(message));
        Assert.AreEqual(HandshakeMessageReadStatus.Complete, read.Status);
        Assert.AreEqual(type, read.Message!.Type);
        return read.Message.Body;
    }
}
